/// Whether .NET's `\w` matches the character.
pub fn is_word(c: char) -> bool {
    let Ok(unit) = u16::try_from(c as u32) else { return false };
    WORD.binary_search_by(|&(low, high)| if unit < low { std::cmp::Ordering::Greater } else if unit > high { std::cmp::Ordering::Less } else { std::cmp::Ordering::Equal }).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn letters_digits_marks_and_connectors_are_words_and_the_rest_is_not() {
        for c in ['a', 'Z', '0', '_', 'é', 'ß', '日', '\u{0301}', '٣', '\u{203F}'] {
            assert!(is_word(c), "{c:?}");
        }
        for c in [' ', '-', '.', '"', '#', '\u{00A0}', '\u{2028}', '😀', '𝐀', '\u{FFFD}'] {
            assert!(!is_word(c), "{c:?}");
        }
        assert!(WORD.windows(2).all(|pair| pair[0].1 < pair[1].0), "the ranges are in order and apart");
    }
}
